preConditionHook:
// THE LEG 1 = LEG 2 MEASURED MOVE (Brooks's AB=CD without the label he
// rejects). A is the start of the first leg, B its end, C the end of the
// pullback, and the target is D = C + multiple * (B - A). For a bull leg:
// A = the swing low before the leg (occurrence 2), B = the swing high that
// ended it (occurrence 1), C = the swing low the pullback ended at
// (occurrence 1). The short mirror runs A = swing high occurrence 2,
// B = swing low occurrence 1, C = swing high occurrence 1, and the SAME
// formula serves both because B - A is negative on that side.
//
// ONLY OCCURRENCES 1 AND 2 ARE READ -- occurrence 3+ is unmeasured in the
// register, so the three anchors come from the two swing-low occurrences and
// the two swing-high occurrences rather than from a third-occurrence call.
//
// THE ORDERING GUARD IS THIS RULE'S OWN CONSTRUCTION, not the merged
// pseudocode's: A, B and C must have printed in that order for the legs to be
// legs at all, so the bars-ago counts must DESCEND, loBar2 > hiBar1 > loBar1
// on the long side (bars-ago, so the older anchor carries the larger count),
// and the first leg must actually be up (hiPx1 > loPx2). Without it an
// interleaved pivot pair would project a target off two unrelated legs. The
// -1 sentinel is guarded on every bar index too: -1 as a PRICE sits under
// every real price and would otherwise read as a valid anchor.
//
// RE-READ EVERY BAR, not frozen at entry -- SwingPivotTarget's convention for
// a structural level, and what the merged pseudocode states. A newly confirmed
// pivot therefore moves the target; PullbackSizedProfitTarget is the rule that
// freezes instead.
//
// toleranceTicks takes the target that many ticks SHORT of D. Ticks are
// written division-first, toleranceTicks * (ctx.MinMove() / ctx.PriceScale()),
// with the tick computed once into tickSz: MinMove and PriceScale are
// per-symbol constants (VERIFIED -- exactly one change print per chart, at
// bar 1), so no history is needed.
//
// PIVOT SCAN inlined from SwingHigh.json per the B-list decision; rules here
// never reference each other. MEASURED (EL_Swing_Probe.txt, @ES 60 min): the
// pivot bar is AT OR ABOVE the pivotStrength OLDER bars and STRICTLY ABOVE the
// pivotStrength NEWER bars -- bars-ago indexing, so the newer bars are the
// smaller k and take el_gt / el_lt, the older el_ge / el_le. Confirmation lag
// is exactly pivotStrength bars, candidate offsets pivotStrength..lookback-1,
// and the neighbourhood reaches pivotStrength bars past the window, so the
// deepest bar touched is lookback - 1 + pivotStrength. Scanning newest-first
// and taking the first two hits reproduces occurrences 1 and 2, which is what
// the twin's SwingHigh / SwingLow calls return. The comparisons carry the
// 2.22e-12 relational tolerance. The low side's tie sense is the mirror of the
// measured high-side rule. No WFSafe_SwingHigh exists, so plain EL governs.
//
// Not PatternHeightMeasuredMoveTarget, whose height is the breakout window's
// own span projected off the extreme that broke -- here the height is the
// PRIOR leg and the projection starts at the PULLBACK extreme, so the two land
// on different prices whenever the pullback is not shallow. Not
// GapMidpointMeasuredMoveTarget (a midpoint projection) and not
// SwingPivotTarget (exits AT a pivot and projects nothing).
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
tickSz = ctx.MinMove() / ctx.PriceScale();
pivS = (int)pivotStrength;
pivW = (int)lookback;
nHi = 0;
nLo = 0;
hiPx1 = -1.0;
hiBar1 = -1.0;
hiPx2 = -1.0;
hiBar2 = -1.0;
loPx1 = -1.0;
loBar1 = -1.0;
loPx2 = -1.0;
loBar2 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHi < 2) {
        nHi = nHi + 1;
        if (nHi == 1) { hiPx1 = high[j]; hiBar1 = (double)j; }
        if (nHi == 2) { hiPx2 = high[j]; hiBar2 = (double)j; }
    }
    if (okLo && nLo < 2) {
        nLo = nLo + 1;
        if (nLo == 1) { loPx1 = low[j]; loBar1 = (double)j; }
        if (nLo == 2) { loPx2 = low[j]; loBar2 = (double)j; }
    }
}
haveUp = (loBar1 != -1.0) && (loBar2 != -1.0) && (hiBar1 != -1.0)
    && el_gt(loBar2, hiBar1) && el_gt(hiBar1, loBar1) && el_gt(hiPx1, loPx2);
haveDn = (hiBar1 != -1.0) && (hiBar2 != -1.0) && (loBar1 != -1.0)
    && el_gt(hiBar2, loBar1) && el_gt(loBar1, hiBar1) && el_lt(loPx1, hiPx2);
tgtUp = loPx1 + multiple * (hiPx1 - loPx2);
tgtDn = hiPx1 + multiple * (loPx1 - hiPx2);
